package local.skyfamily;
import android.graphics.Typeface;import android.graphics.drawable.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public class FrameActivity extends SchoolActivity {
 View observed;final ViewTreeObserver.OnGlobalLayoutListener formLayout=()->{if(observed!=null)normalize(observed);};
 android.graphics.drawable.Drawable controlBackground(){StateListDrawable states=new StateListDrawable();states.addState(new int[]{android.R.attr.state_pressed},shape(palette().rail,palette().accent,16));states.addState(new int[]{android.R.attr.state_selected},shape(palette().surface,palette().accent,16));states.addState(new int[]{},shape(palette().surface,edge,16));return states;}
 TextView label(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setIncludeFontPadding(true);return t;}
 int frameColumns(){int available=getResources().getConfiguration().screenWidthDp-120;return Math.max(1,Math.min(4,available/210));}
 @Override void page(String title){super.page(title);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN);LinearLayout shell=new LinearLayout(this);shell.setBackgroundColor(palette().bg);ScrollView railScroll=new ScrollView(this);railScroll.setFillViewport(true);railScroll.setVerticalScrollBarEnabled(false);shell.addView(railScroll,new LinearLayout.LayoutParams(dp(88),-1));sidebar=new LinearLayout(this);sidebar.setOrientation(1);sidebar.setPadding(dp(6),dp(10),dp(6),dp(10));sidebar.setBackgroundColor(palette().rail);railScroll.addView(sidebar,new ScrollView.LayoutParams(-1,-1));TextView brand=label("SKY",18,palette().accent);brand.setGravity(Gravity.CENTER);brand.setTypeface(Typeface.DEFAULT_BOLD);sidebar.addView(brand,new LinearLayout.LayoutParams(-1,dp(44)));String group=group(title);frameRail("Home",group.equals("Home"),()->home());frameRail("Photos",group.equals("Photos"),()->framePhotos());frameRail("School",group.equals("School"),()->schoolHome());frameRail("Games",group.equals("Games"),()->puzzle());frameRail("Uploads",group.equals("Uploads"),()->uploadHub());frameRail("Settings",group.equals("Settings"),()->settings());LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(16),dp(8),dp(16),0);shell.addView(content,new LinearLayout.LayoutParams(0,-1,1));header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);content.addView(header,new LinearLayout.LayoutParams(-1,dp(64)));TextView heading=label(title,24,fg);heading.setTypeface(Typeface.DEFAULT_BOLD);heading.setMaxLines(1);heading.setEllipsize(TextUtils.TruncateAt.END);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));LinearLayout actions=new LinearLayout(this);header.addView(actions,new LinearLayout.LayoutParams(dp(174),dp(56)));iconControl(actions,"Home",()->home());iconControl(actions,"Full",()->expandPage(true));iconControl(actions,"Rotate",()->screenRotation());ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setClipToPadding(false);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(8),0,dp(24));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));wrapper=new FrameLayout(this);wrapper.addView(shell,new FrameLayout.LayoutParams(-1,-1));exitExpanded=label("Exit fullscreen",16,fg);exitExpanded.setGravity(Gravity.CENTER);exitExpanded.setPadding(dp(16),dp(10),dp(16),dp(10));exitExpanded.setBackground(controlBackground());exitExpanded.setVisibility(View.GONE);FrameLayout.LayoutParams exit=new FrameLayout.LayoutParams(-2,dp(56),Gravity.BOTTOM|Gravity.RIGHT);exit.setMargins(0,0,dp(12),dp(12));wrapper.addView(exitExpanded,exit);exitExpanded.setOnClickListener(v->expandPage(false));setContentView(wrapper);columns=frameColumns();count=0;}
 String group(String title){String s=title.toLowerCase(Locale.US);if(s.equals("home"))return "Home";if(s.contains("school")||s.contains("notebook"))return "School";if(s.contains("upload")||s.contains("qr")||s.contains("scan to"))return "Uploads";if(s.contains("photo")||s.contains("album")||s.contains("immich")||s.contains("gallery"))return "Photos";if(s.contains("game")||s.contains("maze")||s.contains("crossword")||s.contains("guess")||s.equals("snake")||s.equals("pong")||s.equals("falling blocks"))return "Games";if(s.contains("settings")||s.contains("themes")||s.contains("birthday"))return "Settings";return "";}
 void frameRail(String title,boolean selected,Runnable action){LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.setPadding(dp(2),dp(6),dp(2),dp(6));item.setSelected(selected);item.setBackground(controlBackground());item.addView(new ControlIcon(this,title),new LinearLayout.LayoutParams(dp(22),dp(22)));TextView name=label(title,14,selected?palette().accent:fg);name.setGravity(Gravity.CENTER);item.addView(name);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(64));lp.bottomMargin=dp(6);sidebar.addView(item,lp);item.setFocusable(true);item.setContentDescription(title+(selected?" / selected":""));item.setOnClickListener(v->action.run());}
 @Override void text(String value){TextView t=label(value,18,palette().muted);t.setPadding(dp(2),dp(6),dp(2),dp(12));t.setLineSpacing(dp(3),1);body.addView(t);}
 @Override void section(String value){TextView t=label(value,20,fg);t.setTypeface(Typeface.DEFAULT_BOLD);t.setPadding(dp(2),dp(18),0,dp(10));body.addView(t);}
 @Override void button(String title,Runnable action){LinearLayout card=new LinearLayout(this);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(16),dp(12),dp(16),dp(12));card.setMinimumHeight(dp(64));card.setBackground(controlBackground());card.addView(new ControlIcon(this,title),new LinearLayout.LayoutParams(dp(26),dp(26)));TextView name=label(title,18,fg);name.setPadding(dp(14),0,dp(10),0);card.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=label(">",18,palette().muted);card.addView(arrow);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);body.addView(card,lp);card.setContentDescription(title);card.setFocusable(true);card.setOnClickListener(v->action.run());}
 @Override TextView iconControl(LinearLayout row,String title,Runnable action){LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.setPadding(dp(2),dp(3),dp(2),dp(3));item.setMinimumHeight(dp(48));item.setBackground(controlBackground());ControlIcon icon=new ControlIcon(this,title);item.addView(icon,new LinearLayout.LayoutParams(dp(19),dp(19)));TextView name=label(title,14,fg);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);name.setGravity(Gravity.CENTER);item.addView(name);name.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int start,int before,int count){icon.label(s.toString());item.setContentDescription(s);}public void afterTextChanged(Editable e){}});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(dp(2),dp(1),dp(2),dp(1));row.addView(item,lp);item.setFocusable(true);item.setContentDescription(title);item.setOnClickListener(v->action.run());return name;}
 @Override TextView mini(LinearLayout row,String title,Runnable action){return iconControl(row,title,action);}
 @Override void inkControl(LinearLayout row,String title,Runnable action){iconControl(row,title,action);}
 @Override EditText input(String hint,String value){EditText edit=super.input(hint,value);edit.setTextSize(18);edit.setTextColor(fg);edit.setHintTextColor(palette().muted);edit.setMinHeight(dp(60));edit.setPadding(dp(14),dp(12),dp(14),dp(12));edit.setBackground(shape(palette().surface,edge,16));NativePickers.bind(this,edit);return edit;}
 void frameCard(LinearLayout row,String title,String detail,Runnable action){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(14),dp(14),dp(12));card.setBackground(controlBackground());card.addView(new ControlIcon(this,title),new LinearLayout.LayoutParams(dp(26),dp(26)));TextView name=label(title,20,fg);name.setTypeface(Typeface.DEFAULT_BOLD);name.setPadding(0,dp(8),0,dp(4));name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);card.addView(name);TextView description=label(detail,14,palette().muted);description.setMaxLines(2);description.setEllipsize(TextUtils.TruncateAt.END);card.addView(description);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(170),1);lp.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(card,lp);card.setFocusable(true);card.setContentDescription(title+". "+detail);card.setOnClickListener(v->action.run());}
 @Override void tile(String title,String subtitle,String mark,int color,Runnable action){if(columns<1)columns=frameColumns();if(count%columns==0){grid=new LinearLayout(this);body.addView(grid);}frameCard(grid,title,subtitle,action);count++;}
 @Override void gameCard(LinearLayout row,String title,String description,Runnable action){frameCard(row,title,description,action);}
 @Override void home(){page("Home");LinearLayout today=new LinearLayout(this);today.setGravity(Gravity.CENTER_VERTICAL);TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setFormat24Hour("HH:mm");clock.setTextSize(30);clock.setTextColor(fg);today.addView(clock,new LinearLayout.LayoutParams(0,dp(48),1));TextView date=label(new java.text.SimpleDateFormat("EEE, d MMM",Locale.getDefault()).format(new Date()),16,palette().muted);today.addView(date);body.addView(today);tile("Photos","Albums and fullscreen playback","",accent,()->framePhotos());tile("School","Class notes and assignments","",accent,()->schoolHome());tile("Books","Your books and PDFs","",accent,()->bookshelf());tile("Create","Drawing, colouring and projects","",accent,()->frameCreate());tile("Games","Arcade and word puzzles","",accent,()->puzzle());tile("Weather","Saved local forecast","",accent,()->planetaryData());tile("Uploads","QR receiving and book import","",accent,()->uploadHub());tile("Explore","Planner, notes, media and more","",accent,()->frameExplore());endgrid();ArrayList<String> names=ThemeArt.today(prefs);if(!names.isEmpty())text("Happy birthday, "+TextUtils.join(", ",names)+"!");String scene=ThemeArt.scene(prefs);if(!scene.equals("off"))body.addView(new ThemeArt.Scene(this,scene,prefs.getBoolean("visual.motion",false)),new LinearLayout.LayoutParams(-1,dp(100)));shownDay=ThemeArt.dateKey(Calendar.getInstance());atHome=true;armIdle();}
 void framePhotos(){page("Photos");button(token.isEmpty()?"Connect or unlock Immich":"Browse Immich library",()->immich());button("Choose albums",()->albums());button("Play Immich gallery",()->startGallery(false));button("Play uploaded-photo gallery",()->startGallery(true));button("Gallery and idle playback settings",()->gallerySettings());}
 void frameCreate(){page("Create");tile("Drawing","Open a blank canvas","",accent,()->drawing(false));tile("Colouring","Choose a colouring page","",accent,()->drawing(true));tile("Projects","Continue saved artwork","",accent,()->projectsEntry());endgrid();}
 void frameExplore(){page("Explore");tile("Calendar","Your local day entries","",accent,()->calendar());tile("Daily notes","Separate from School","",accent,()->notes());tile("Pocket creature","Feed and train your companion","",accent,()->pet());tile("Space","Official viewing destinations","",accent,()->space());tile("Cameras","Provider viewing pages","",accent,()->cameras());tile("News","Built-in and custom RSS","",accent,()->news());tile("Santa","Countdown and fictional preview","",accent,()->santa());tile("Cast receiver","Enable local DLNA receiving","",accent,()->castSetup());tile("Apps","Installed applications","",accent,()->apps());endgrid();}
 @Override public void onContentChanged(){super.onContentChanged();if(prefs==null)return;View root=findViewById(android.R.id.content);if(root==null||root==observed)return;if(observed!=null&&observed.getViewTreeObserver().isAlive())observed.getViewTreeObserver().removeOnGlobalLayoutListener(formLayout);observed=root;root.getViewTreeObserver().addOnGlobalLayoutListener(formLayout);}
 void normalize(View view){if(view instanceof android.webkit.WebView)return;NativePickers.bind(this,view);if(view instanceof TextView){TextView text=(TextView)view;float sp=text.getTextSize()/getResources().getDisplayMetrics().scaledDensity;if(sp<13.9f)text.setTextSize(14);}if(view instanceof CheckBox){CheckBox box=(CheckBox)view;box.setTextColor(fg);if(box.getMinimumHeight()<dp(52))box.setMinHeight(dp(52));if(box.getTextSize()/getResources().getDisplayMetrics().scaledDensity<18)box.setTextSize(18);}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)normalize(group.getChildAt(i));}}
 @Override protected void onDestroy(){if(observed!=null&&observed.getViewTreeObserver().isAlive())observed.getViewTreeObserver().removeOnGlobalLayoutListener(formLayout);observed=null;super.onDestroy();}
}
